--- a/src/paginate.mjs
+++ b/src/paginate.mjs
@@ -1,5 +1,5 @@
 export function paginate(items, page, pageSize) {
-  const start = page * pageSize
-  const pages = Math.floor(items.length / pageSize)
+  const start = (page - 1) * pageSize
+  const pages = Math.ceil(items.length / pageSize)
   return { items: items.slice(start, start + pageSize), page, pages }
 }

--- a/src/template.mjs
+++ b/src/template.mjs
@@ -1,11 +1,13 @@
+const ENTITIES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }
+
 export function escapeHtml(value) {
-  return String(value)
+  return String(value).replace(/[&<>"']/g, character => ENTITIES[character])
 }

 export function render(template, values) {
-  let output = template
-  for (const [name, value] of Object.entries(values)) {
-    output = output.replaceAll(`{{${name}}}`, String(value))
-  }
-  return output
+  return template.replace(/\{\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}\}/g, (_, name) => {
+    const value = values[name]
+    if (value === undefined || value === null) throw new ReferenceError(`missing template value: ${name}`)
+    return escapeHtml(value)
+  })
 }

--- a/src/csv.mjs
+++ b/src/csv.mjs
@@ -1,3 +1,40 @@
 export function parseCsvLine(line) {
-  return line.split(',')
+  const fields = []
+  let field = ''
+  let index = 0
+  let quoted = false
+  while (index <= line.length) {
+    if (!quoted && field === '' && line[index] === '"') {
+      quoted = true
+      index += 1
+      let closed = false
+      while (index < line.length) {
+        if (line[index] === '"') {
+          if (line[index + 1] === '"') {
+            field += '"'
+            index += 2
+            continue
+          }
+          closed = true
+          index += 1
+          break
+        }
+        field += line[index]
+        index += 1
+      }
+      if (!closed) throw new SyntaxError('unterminated quoted field')
+      continue
+    }
+    if (index === line.length || line[index] === ',') {
+      fields.push(field)
+      field = ''
+      quoted = false
+      index += 1
+      continue
+    }
+    if (quoted) throw new SyntaxError(`unexpected character after closing quote at ${index}`)
+    field += line[index]
+    index += 1
+  }
+  return fields
 }

--- a/src/intervals.mjs
+++ b/src/intervals.mjs
@@ -1,3 +1,9 @@
 export function mergeIntervals(intervals) {
-  throw new Error('TODO: merge overlapping intervals')
+  const merged = []
+  for (const [start, end] of intervals) {
+    const last = merged.at(-1)
+    if (last && start < last[1]) last[1] = Math.max(last[1], end)
+    else merged.push([start, end])
+  }
+  return merged
 }

--- a/src/retry.mjs
+++ b/src/retry.mjs
@@ -1,12 +1,13 @@
 export async function retry(operation, { attempts, baseDelayMs, sleep }) {
-  let lastError
-  for (let attempt = 0; attempt <= attempts; attempt++) {
+  if (!Number.isInteger(attempts) || attempts < 1) throw new RangeError('attempts must be a positive integer')
+  const errors = []
+  for (let attempt = 1; attempt <= attempts; attempt++) {
+    if (attempt > 1) await sleep(baseDelayMs * 2 ** (attempt - 2))
     try {
       return await operation(attempt)
     } catch (error) {
-      lastError = error
-      await sleep(baseDelayMs)
+      errors.push(error)
     }
   }
-  throw lastError
+  throw new AggregateError(errors, `operation failed after ${attempts} attempts`)
 }
